INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Self-Care for Strong Leaders'), 1, 'Phase 1: The Signal', 'When your body speaks before you do', 'Your body is not your enemy. It is your earliest and most honest leadership advisor. Listening to it is the first act of sustainable leadership.', 'This opening scenario introduces the central theme: self-care as leadership intelligence, not indulgence. It helps learners recognise the physical and emotional signals of depletion before they reach crisis point — and practise making a deliberate choice in response.');

