INSERT INTO component_mcq (question) VALUES ('You are in the middle of an intense work week. You have delivered on every deadline, supported your team, and attended every meeting. But now, on Thursday evening, you feel completely flat — no energy left, difficulty concentrating, and a creeping irritability you cannot explain. Your calendar tomorrow is already full.');
