INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Self-Care for Strong Leaders'), 2, 'Phase 2: The Ask', 'When taking care of yourself feels selfish', 'Choosing yourself is not abandoning others. It is making sure that when you show up, you are truly present — not depleted and resentful.', 'This scenario explores the most common internal barrier to self-care: the belief that prioritising yourself is selfish or unhelpful. It helps learners practise saying a clear, caring no — and recognise that a well-placed boundary protects the quality of their contribution, not just their comfort.');

