INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Self-Care for Strong Leaders'), 3, 'Phase 3: The Habit', 'Building something that actually lasts', 'The best self-care habit is not the most beautiful one. It is the one you will actually do — on Tuesday morning, when you are tired, before your day takes over.', 'This scenario addresses the gap between intention and habit — one of the most common failure points in self-care. It helps learners apply the principle of consistency over perfection, and design a practice that fits their actual life rather than an aspirational one.');

