INSERT INTO component_mcq (question) VALUES ('You have decided to start a self-care practice. You want it to be consistent and realistic. You know from experience that big intentions often fade after a few days. You are thinking about what approach would actually work for your life — not the ideal version of your life, but the real one, this week.');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You have decided to start a self-care practice. You want it to be consistent and realistic. You know from experience that big intentions often fade after a few days. You are thinking about what approach would actually work for your life — not the ideal version of your life, but the real one, this week.' ORDER BY id DESC LIMIT 1), 'You design an ambitious morning routine: exercise, journaling, meditation, and a healthy breakfast — every day.', 'Ambition in self-care is understandable — but complexity is the enemy of consistency. When one element fails, the whole routine collapses. Start with one anchor habit and build from there. Perfection is not the goal; repetition is.');
