INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Self-Care for Strong Leaders'), 4, 'Phase 4: The Voice', 'What you say to yourself when no one is watching', 'Confidence grows where care begins — and that care starts with the voice inside your head. You deserve the same kindness you would offer anyone you lead.', 'This scenario introduces self-compassion as a core dimension of self-care. It helps learners recognise that how they speak to themselves directly affects their energy, confidence, and leadership capacity — and that inner kindness is a skill, not a personality trait.');

