INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You made a mistake at work today — a small one, but visible. In the hours that follow, you notice the internal voice: the one that replays the moment, questions your competence, and compares you to others who seem to handle things more easily. You know this voice well. You are wondering how to respond to it.' ORDER BY id DESC LIMIT 1), 'You notice the voice and ask: "What would I say to a friend who made this same mistake?"', 'This is a powerful self-compassion practice. We are almost always kinder to others than to ourselves in the same situation. Applying that same generosity to yourself is not weakness — it is emotional intelligence, and it builds the confidence that leadership requires.');
