INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You made a mistake at work today — a small one, but visible. In the hours that follow, you notice the internal voice: the one that replays the moment, questions your competence, and compares you to others who seem to handle things more easily. You know this voice well. You are wondering how to respond to it.' ORDER BY id DESC LIMIT 1), 'You distract yourself — scroll, snack, stay busy — until the feeling passes.', 'Distraction offers temporary relief but not resolution. The inner critic returns, often louder, because it was never addressed. Noticing and naming a difficult emotion — even briefly — is more restorative than bypassing it.');
