INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Self-Care for Strong Leaders'), 5, 'Phase 5: The Commitment', 'Leading from a place of balance', 'You have completed the Self-Care for Strong Leaders simulator. Your result reflects where you stand today in your relationship with your own energy, boundaries, and self-compassion. Strong leaders do not run on empty. They lead from a place of balance, awareness, and inner strength — and that place is built one intentional choice at a time.', 'This closing scenario supports integration and commitment. It helps learners move from insight to intention, and choose a concrete orientation for the days ahead. The three options represent different entry points — habit, honesty, and awareness — all of which are valid starting places for sustainable self-care leadership.');

