INSERT INTO component_mcq (question) VALUES ('You are at the end of this module. You have reflected on your energy patterns, your boundaries, your inner voice, and the habits that actually fit your life. You now have a clearer picture of what self-care means for you — not in theory, but in practice. The question is: what will you take with you when the next demanding week arrives?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You are at the end of this module. You have reflected on your energy patterns, your boundaries, your inner voice, and the habits that actually fit your life. You now have a clearer picture of what self-care means for you — not in theory, but in practice. The question is: what will you take with you when the next demanding week arrives?' ORDER BY id DESC LIMIT 1), 'You reflect: "I will protect at least one small moment each day that belongs entirely to me."', 'Strong commitment. One protected moment per day — however small — anchors the entire practice. It teaches you that your energy matters, and it teaches others the same. Leadership that is sustainable begins exactly here.');
