INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You are at the end of this module. You have reflected on your energy patterns, your boundaries, your inner voice, and the habits that actually fit your life. You now have a clearer picture of what self-care means for you — not in theory, but in practice. The question is: what will you take with you when the next demanding week arrives?' ORDER BY id DESC LIMIT 1), 'You reflect: "Next time I feel depleted, I will pause and ask what I need — instead of just pushing through."', 'Excellent. This is perhaps the most powerful shift of all: from automatic pushing to deliberate pausing. That one question — "what do I need right now?" — is a complete self-care practice in itself. It reconnects you to your own intelligence.');
