-- Feedback for metric 'Energy Management' (Score 0-49)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Self-Care for Strong Leaders'), (SELECT id FROM simulator_metric WHERE name = 'Energy Management' LIMIT 1), 0, 49, 'You are becoming aware of your energy patterns and what it feels like when your reserves are low.', 'You may override your body''s signals and keep going until depletion forces a stop. This can affect your clarity, mood, and decision-making.', 'At the end of each day, rate your energy from 1–10. After one week, look for the pattern.', NULL, 'This module can help you identify the root causes of energy drain and build a sustainable daily rhythm.');

-- Feedback for metric 'Energy Management' (Score 50-85)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Self-Care for Strong Leaders'), (SELECT id FROM simulator_metric WHERE name = 'Energy Management' LIMIT 1), 50, 85, 'You have some practices that help you recover and maintain energy across demanding periods.', 'Under high pressure, you may still revert to pushing through rather than pausing to recharge.', 'Identify your single highest-energy moment of the day and protect it for your most important work.', NULL, 'This module can help you use energy management as a strategic leadership tool, not just a personal habit.');

-- Feedback for metric 'Energy Management' (Score 85-100)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Self-Care for Strong Leaders'), (SELECT id FROM simulator_metric WHERE name = 'Energy Management' LIMIT 1), 85, 100, 'You manage your energy with intention and treat recovery as a non-negotiable part of your leadership.', 'None. You demonstrate strong self-awareness and sustainable performance habits.', 'Once a week, reflect on one moment when protecting your energy led to a better outcome for you or your team.', NULL, 'This module can help you extend your energy management practices into team culture and systemic leadership.');

